# run_explore.py – Stage 0 exploration & split\n\n"""\nStage 0:\n- Load all TSV files (chunk‑wise to avoid OOM).\n- Verify that each file is TAB‑separated (header contains '\t').\n- Print basic schema, row counts, null statistics, country distribution,\n  and ground‑truth singleton rate.\n- Create a GroupKFold split on source1_entity_id (no leakage) and\n  write two files: train_ids.txt and val_ids.txt (one ID per line).\nThese files will be used by later stages.\n\nThe script is intentionally lightweight and has no external dependencies\nbesides pandas and scikit‑learn, which are already installed.\n\nUsage:\n    python -m business_entity_resolution.src.run_explore\n\nOutputs are printed to stdout and the split files are written under\n'code/business_entity_resolution/data/'.\n"""\n\nimport os, sys\nfrom collections import Counter\nimport pandas as pd\nfrom sklearn.model_selection import KFold\n\nBASE_DIR = os.path.abspath(os.path.join(os.path.dirname(__file__), "../../.."))\nDATA_DIR = os.path.join(BASE_DIR, "dataset")\nTRAIN_DIR = os.path.join(DATA_DIR, "train")\nTEST_DIR = os.path.join(DATA_DIR, "test")\nOUTPUT_SPLIT_DIR = os.path.join(BASE_DIR, "code", "business_entity_resolution", "data")\nos.makedirs(OUTPUT_SPLIT_DIR, exist_ok=True)\n\ndef verify_tab_separator(path):\n    with open(path, 'r', encoding='utf-8') as f:\n        first_line = f.readline()\n    if '\t' not in first_line:\n        raise ValueError(f"File {path} does not appear to be TAB‑separated.")\n\ndef file_stats(path, expected_cols=None):\n    verify_tab_separator(path)\n    chunk_iter = pd.read_csv(path, sep='\t', dtype=str, chunksize=500_000)\n    total_rows = 0\n    null_counts = Counter()\n    country_counts = Counter()\n    for chunk in chunk_iter:\n        total_rows += len(chunk)\n        if expected_cols:\n            missing = set(expected_cols) - set(chunk.columns)\n            if missing:\n                raise ValueError(f"Missing columns {missing} in {path}")\n        for col in chunk.columns:\n            nulls = (chunk[col].isna() | (chunk[col].astype(str).str.strip() == "")).sum()\n            null_counts[col] += int(nulls)\n        if 'country' in chunk.columns:\n            country_counts.update(chunk['country'].fillna('').value_counts().to_dict())\n    return {'rows': total_rows, 'nulls': dict(null_counts), 'countries': dict(country_counts)}\n\ndef ground_truth_stats(path):\n    df = pd.read_csv(path, sep='\t', dtype=str)\n    total = len(df)\n    singletons = (df['matched_entity_ids'].fillna('').str.strip() == '').sum()\n    singleton_rate = singletons / total\n    match_counts = df['matched_entity_ids'].fillna('').str.split(',').apply(lambda x: 0 if x==[''] else len(x))\n    avg_matches = match_counts.mean()\n    max_matches = match_counts.max()\n    return {'total': total, 'singletons': int(singletons), 'singleton_rate': singleton_rate, 'avg_matches': avg_matches, 'max_matches': int(max_matches)}\n\ndef create_split(source1_path, n_splits=5, random_state=42):\n    df = pd.read_csv(source1_path, sep='\t', dtype=str, usecols=['entity_id'])\n    ids = df['entity_id'].values\n    kf = KFold(n_splits=n_splits, shuffle=True, random_state=random_state)\n    train_idx, val_idx = next(kf.split(ids))\n    train_ids = ids[train_idx]\n    val_ids = ids[val_idx]\n    train_path = os.path.join(OUTPUT_SPLIT_DIR, 'train_ids.txt')\n    val_path = os.path.join(OUTPUT_SPLIT_DIR, 'val_ids.txt')\n    with open(train_path, 'w', encoding='utf-8') as f:\n        for i in train_ids:\n            f.write(i + '\n')\n    with open(val_path, 'w', encoding='utf-8') as f:\n        for i in val_ids:\n            f.write(i + '\n')\n    return train_path, val_path, len(train_ids), len(val_ids)\n\ndef main():\n    print("--- Stage 0: Data exploration & split ---\n")\n    train_src_files = {\n        'source1': os.path.join(TRAIN_DIR, 'train_source1.tsv'),\n        'source2': os.path.join(TRAIN_DIR, 'train_source2.tsv'),\n        'source3': os.path.join(TRAIN_DIR, 'train_source3.tsv'),\n        'ground_truth': os.path.join(TRAIN_DIR, 'train_ground_truth.tsv')\n    }\n    for name, p in train_src_files.items():\n        if name == 'ground_truth':\n            stats = ground_truth_stats(p)\n            print(f"[Ground Truth] rows={stats['total']}, singleton_rate={stats['singleton_rate']:.3%}, avg_matches={stats['avg_matches']:.2f}, max={stats['max_matches']}")\n        else:\n            stats = file_stats(p, expected_cols=['entity_id','business_name','business_address','country'])\n            print(f"[{name}] rows={stats['rows']:,}, nulls={stats['nulls']}, country_counts={stats['countries']}")\n    test_src_files = {\n        'test_source1': os.path.join(TEST_DIR, 'test_source1.tsv'),\n        'test_source2': os.path.join(TEST_DIR, 'test_source2.tsv'),\n        'test_source3': os.path.join(TEST_DIR, 'test_source3.tsv')\n    }\n    for name, p in test_src_files.items():\n        stats = file_stats(p, expected_cols=['entity_id','business_name','business_address','country'])\n        print(f"[Test {name}] rows={stats['rows']:,}, country_counts={stats['countries']}")\n    train_path, val_path, n_train, n_val = create_split(train_src_files['source1'])\n    print(f"\nCreated train/validation split: {n_train:,} train IDs, {n_val:,} validation IDs")\n    print(f"Train IDs saved to: {train_path}")\n    print(f"Val IDs saved to: {val_path}\n")\n\nif __name__ == '__main__':\n    main()\n
